<script setup lang="ts">
import { ref,watch,onMounted,onBeforeUnmount } from 'vue'
import { ElMessage } from 'element-plus'
import type { Api } from './api'
import { errorName } from './labels'
import ScoreRing from './ScoreRing.vue'
interface Fact {id:string;category:string;content:string;source_type:string;source_version:number;source_task_id?:string;locator?:string;quote?:string}
interface Check {condition:string;status:string;reason?:string;evidence:Fact[]}
interface Entry {id:string;talent_id:string;state:string;group:string;error_code:string|null;profile_stale:boolean;snapshot:{name:string;kind:string;version:number;facts:Fact[]};result:{score:number|null;checks:Check[];preferred:Check[];explanation:string;dense_score?:number;semantic_rrf?:number;lexical_score?:number;components?:Record<string,[number,number]>}|null}
interface Run {id:string;state:string;outcome:string|null;run_version:number;requirement_version:number;requirement_stale:boolean;rules_stale?:boolean;requirement_status:string;created_at:number;total:number;counts:Record<string,number>;retryable:boolean;rules:Record<string,unknown>;requirement_snapshot:Record<string,unknown>;scope_snapshot:Record<string,unknown>;attempts:{run_version:number;state:string}[];error_code:string|null}
const props=defineProps<{api:Api;requirementId:string;initialRunId?:string;version:number;activeVersion:number|null;status:string;canRun:boolean;canAssociate:boolean}>()
const emit=defineEmits<{open:[id:string];task:[id:string]}>()
const showStart=ref(false)
const busy=ref(false),runs=ref<Run[]>([]),historyPage=ref(1),historyTotal=ref(0),selected=ref<Run|null>(null),entries=ref<Entry[]>([]),page=ref(1),total=ref(0),group=ref(''),focused=ref<Entry|null>(null)
const includeInternal=ref(false),skill=ref(''),weights=ref({evidence_weight:50,preferred_weight:20,semantic_weight:30}),key=ref(crypto.randomUUID())
let generation=0,polling=false
const names:Record<string,string>={queued:'待处理',running:'处理中',succeeded:'已完成',failed:'失败',pending:'待处理',evaluated:'已评估',pass:'满足',unknown:'待核对',fail:'不满足',complete:'全部处理完成',partial:'部分失败',expired:'租约过期'}
async function run(fn:()=>Promise<void>) {busy.value=true;try{await fn()}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
async function loadHistory(){const data=await props.api<{items:Run[];total:number}>(`/requirements/${props.requirementId}/matches?offset=${(historyPage.value-1)*20}&limit=20`);runs.value=data.items;historyTotal.value=data.total}
async function loadResults(){if(!selected.value)return;const token=generation,id=selected.value.id;const data=await props.api<{items:Entry[];total:number}>(`/matches/${id}/results?offset=${(page.value-1)*20}&limit=20&group=${group.value}`);if(token!==generation)return;entries.value=data.items;total.value=data.total;focused.value=data.items.find(e=>e.id===focused.value?.id)||data.items[0]||null}
async function open(item:Run){generation++;selected.value=item;entries.value=[];total.value=0;page.value=1;group.value='';focused.value=null;await refresh()}
async function refresh(){if(!selected.value)return;const id=selected.value.id,token=generation;try{const item=await props.api<Run>(`/matches/${id}`);if(token!==generation)return;selected.value=item;await loadResults()}catch(error){if(token===generation){selected.value=null;entries.value=[];focused.value=null}throw error}}
async function start(){await run(async()=>{const item=await props.api<Run>(`/requirements/${props.requirementId}/matches`,'POST',{version:props.version,include_internal:includeInternal.value,skill:skill.value,rules:weights.value},key.value);key.value=crypto.randomUUID();showStart.value=false;await loadHistory();await open(item)})}
async function retry(){await run(async()=>{const item=await props.api<Run>(`/matches/${selected.value!.id}/retry`,'POST',{version:selected.value!.run_version});await open(item)})}
async function associate(entry:Entry,linked:boolean){await run(async()=>{await props.api(`/requirements/${props.requirementId}/talents/${entry.talent_id}`,'PUT',{talent_version:entry.snapshot.version,linked});ElMessage.success(linked?'已标记应聘关系；匹配范围不因此改变':'已取消应聘关系')})}
function rowClass({row}:{row:Entry}){return row.id===focused.value?.id?'is-current-match':''}
// 决策摘要：先回答“满足多少、缺什么”，逐条证据仍在下方展开供核对。
function conditionCounts(entry:Entry){
  const all=[...(entry.result?.checks||[]),...(entry.result?.preferred||[])]
  return {pass:all.filter(c=>c.status==='pass').length,unknown:all.filter(c=>c.status==='unknown').length,fail:all.filter(c=>c.status==='fail').length,total:all.length}
}
function resetKey(){key.value=crypto.randomUUID()}
const timer=setInterval(()=>{if(!polling&&selected.value&&['queued','running'].includes(selected.value.state)){polling=true;void refresh().catch(e=>{selected.value=null;entries.value=[];focused.value=null;ElMessage.error((e as Error).message)}).finally(()=>{polling=false})}},2500)
async function openInitial(){if(props.initialRunId)await open(await props.api<Run>('/matches/'+props.initialRunId));else if(runs.value[0])await open(runs.value[0])}
watch(()=>props.initialRunId,()=>void run(openInitial))
onMounted(()=>void run(async()=>{await loadHistory();await openInitial()}))
onBeforeUnmount(()=>{generation++;clearInterval(timer)})
</script>
<template>
  <section class="matches" data-testid="match-workspace">
    <div class="result-heading"><div><h2>匹配结果</h2><p class="muted">硬条件分组优先，分数仅用于本次范围内辅助排序。</p></div><el-button v-if="canRun" type="primary" :disabled="status!=='active'" @click="showStart=true">发起新匹配</el-button></div>
    <el-alert v-if="status!=='active'" type="warning" :closable="false" title="岗位未生效或已停用，不能发起新匹配；历史结果仍可查看。"/>
    <div class="match-controls"><label for="match-history">匹配批次</label><el-select id="match-history" :model-value="selected?.id" placeholder="暂无匹配历史" @change="(id:string)=>{const r=runs.find(r=>r.id===id);if(r)run(()=>open(r))}"><el-option v-for="r in runs" :key="r.id" :value="r.id" :label="`${new Date(r.created_at*1000).toLocaleString()} · 岗位 v${r.requirement_version} · ${names[r.state]}`"/></el-select><el-button :loading="busy" @click="run(async()=>{await loadHistory();await refresh()})">刷新结果</el-button></div>
    <el-pagination v-if="historyTotal>20" v-model:current-page="historyPage" :total="historyTotal" :page-size="20" layout="total,prev,pager,next" @current-change="()=>run(loadHistory)"/>
    <section v-if="selected" data-testid="match-detail">
      <el-alert v-if="selected.requirement_stale||selected.requirement_status!=='active'" type="warning" :closable="false" title="需求已有新有效版本或已停用，本次结果仅供历史参考"/>
      <el-alert v-if="selected.rules_stale" type="warning" :closable="false" title="这是已失效规则生成的历史结果，请发起新匹配；不要将旧分组和分数当成当前结论"/>
      <div class="run-summary"><span><strong>{{names[selected.state]}}</strong> · {{names[selected.outcome||'']||'等待完成'}} · 岗位 v{{selected.requirement_version}}</span><span>当前授权可见 {{selected.total}} 人 · 已评估 {{selected.counts.evaluated}} · 失败 {{selected.counts.failed}} · 待处理 {{selected.counts.pending}}</span></div>
      <el-alert v-if="selected.error_code" :title="errorName[selected.error_code]||selected.error_code" type="error" :closable="false"/>
      <el-button v-if="canRun&&selected.retryable" @click="retry">重试可恢复失败（保留原快照）</el-button>
      <el-radio-group v-model="group" class="result-groups" aria-label="结果分组" @change="page=1;run(loadResults)"><el-radio-button value="">全部</el-radio-button><el-radio-button v-for="g in ['pass','unknown','fail','failed','pending']" :key="g" :value="g">{{names[g]}}</el-radio-button></el-radio-group>
      <div v-loading="busy" class="match-result-layout">
        <section class="match-list" aria-label="匹配人才列表"><el-table :data="entries" :row-class-name="rowClass" row-key="id" @row-click="(item:Entry)=>focused=item" data-testid="match-results"><el-table-column label="人才" min-width="130"><template #default="{row}"><button class="result-person" @click="focused=row">{{row.snapshot.name}}</button><span class="cell-meta">{{row.snapshot.kind==='internal'?'内部员工':'外部候选人'}}</span></template></el-table-column><el-table-column label="硬条件 / 执行" min-width="115"><template #default="{row}"><el-tag :type="row.group==='pass'?'success':row.group==='unknown'?'warning':row.group==='fail'?'danger':'info'">{{names[row.group]||names[row.state]}}</el-tag><span v-if="row.error_code" class="cell-meta">{{errorName[row.error_code]||row.error_code}}</span></template></el-table-column><el-table-column label="匹配分" width="76" align="center"><template #default="{row}"><ScoreRing :score="row.state==='evaluated'?(row.result?.score??null):null" :size="36" :pending="row.state==='evaluated'&&row.result?.score==null"/><span v-if="row.profile_stale" class="cell-meta">档案已更新</span></template></el-table-column></el-table><el-empty v-if="!entries.length" description="当前分组暂无人才" :image-size="48"/><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @current-change="()=>run(loadResults)"/></section>
        <section v-if="focused" class="match-evidence" data-testid="match-evidence" aria-label="选中人才匹配解释"><div class="evidence-heading"><div><h2>{{focused.snapshot.name}}</h2><span class="muted">匹配时档案 v{{focused.snapshot.version}}</span></div><el-button @click="emit('open',focused.talent_id)">打开画像</el-button></div><el-alert v-if="focused.profile_stale" type="warning" :closable="false" title="当前档案已更新；下列内容为匹配时的快照。"/>
          <div v-if="focused.result" class="decision-summary"><ScoreRing :score="focused.result.score" :size="56"/><div class="decision-text"><div class="decision-line"><el-tag :type="focused.group==='pass'?'success':focused.group==='unknown'?'warning':focused.group==='fail'?'danger':'info'" size="small">{{names[focused.group]||'未分组'}}</el-tag><span class="decision-counts">满足 {{conditionCounts(focused).pass}} · 待核对 {{conditionCounts(focused).unknown}} · 不满足 {{conditionCounts(focused).fail}}</span></div><p class="decision-note">排序参考值只在本批次 {{selected?.total??0}} 人范围内有效，不代表能力评分或录用概率。</p></div></div>
          <p class="pre-line match-explanation">{{focused.result?.explanation}}</p><p v-if="focused.error_code">执行失败：{{errorName[focused.error_code]||focused.error_code}}，未生成完整匹配分。</p>
          <div v-for="check in [...(focused.result?.checks||[]),...(focused.result?.preferred||[])]" :key="check.condition" class="condition-evidence"><strong>{{check.condition}}：{{names[check.status]}}</strong><p>{{check.reason}}</p><blockquote v-for="fact in check.evidence" :key="fact.id"><p>{{fact.content}}</p><span class="muted">{{fact.source_type==='manual'?'人工维护':'简历声明'}} · 来源 v{{fact.source_version}}</span><p v-if="fact.quote">原文：{{fact.quote}}<span v-if="fact.locator"> · {{fact.locator}}</span></p><el-button v-if="fact.source_task_id" link type="primary" @click="emit('task',fact.source_task_id)">查看解析出处</el-button></blockquote><p v-if="!check.evidence.length" class="muted">没有可核对依据，需补充资料。</p></div>
          <div v-if="canAssociate" class="evidence-actions"><el-button @click="associate(focused,true)">标记应聘</el-button><el-button @click="associate(focused,false)">取消应聘</el-button></div>
          <details class="match-diagnostics"><summary>规则、范围与快照详情</summary><p>范围在启动时固定，后续新增人才不加入；历史读取仍受当前权限约束。</p><p>稠密相关性 {{focused.result?.dense_score??'未生成'}} · BM25 {{focused.result?.lexical_score??'未生成'}} · RRF {{focused.result?.semantic_rrf??'未完成排序'}}</p><pre>{{JSON.stringify({rules:selected.rules,scope:selected.scope_snapshot,requirement:selected.requirement_snapshot,attempts:selected.attempts,profile:focused.snapshot},null,2)}}</pre></details>
        </section><el-empty v-else description="选择人才查看条件、解释和证据" :image-size="48"/>
      </div>
    </section><el-empty v-else description="暂无匹配结果，岗位生效后可发起匹配"/>
    <el-dialog v-model="showStart" title="发起新匹配" width="min(650px,94vw)" :close-on-click-modal="false"><p>使用已生效岗位 v{{activeVersion??'无'}}，默认评估当前权限内全部外部人才；不要求人才已关联应聘岗位。开始后范围与资料版本固定。</p><el-form label-position="top" :disabled="busy||!canRun" @change="resetKey"><el-form-item label="评估范围"><el-checkbox v-model="includeInternal">同时包含内部员工（排除目标部门现任）</el-checkbox></el-form-item><el-form-item label="额外技能筛选（可不填，按原文包含）"><el-input v-model="skill" clearable @input="resetKey"/></el-form-item><details><summary>排序权重设置</summary><el-form-item label="证据覆盖权重"><el-input-number v-model="weights.evidence_weight" :min="0" :max="99"/></el-form-item><el-form-item label="加分项权重"><el-input-number v-model="weights.preferred_weight" :min="0" :max="99"/></el-form-item><el-form-item label="语义权重"><el-input-number v-model="weights.semantic_weight" :min="1" :max="100"/></el-form-item><p class="muted">三项合计100；无对应条件的项重新归一。分数不代表能力、录用概率，也不能跨批次直接比较。</p></details></el-form><template #footer><el-button @click="showStart=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="status!=='active'" @click="start">确认范围并开始匹配</el-button></template></el-dialog>
  </section>
</template>
<style scoped>
.decision-summary{display:flex;align-items:center;gap:14px;padding:14px 16px;margin:12px 0;border:1px solid var(--border);border-radius:12px;background:var(--surface-muted)}
.decision-text{min-width:0;flex:1}
.decision-line{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.decision-counts{font-size:13px;font-weight:600;color:var(--text);font-variant-numeric:tabular-nums}
.decision-note{margin:5px 0 0;font-size:11px;color:var(--text-tertiary);line-height:1.6}
.match-explanation{font-size:13px;line-height:1.8;color:var(--text);margin:10px 0 4px}
.result-heading,.evidence-heading{display:flex;justify-content:space-between;align-items:center;gap:12px}.result-heading h2,.evidence-heading h2{margin:0}.result-heading p{margin:5px 0}.match-controls{display:flex;align-items:center;gap:10px;margin:14px 0;flex-wrap:wrap}.match-controls .el-select{width:min(440px,100%)}.match-controls label{font-size:13px}.run-summary{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:12px 16px;border:1px solid var(--border);background:var(--surface);border-radius:8px;font-size:13px}.result-groups{margin:14px 0;flex-wrap:wrap}.match-result-layout{display:grid;grid-template-columns:minmax(350px,1fr) minmax(340px,1fr);gap:16px;align-items:start}.match-list,.match-evidence{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);min-width:0;padding:16px}.match-list :deep(.el-table){margin:0}.match-list :deep(.is-current-match>td){background:var(--accent-soft)}.match-evidence{max-height:calc(100dvh - 320px);min-height:280px;overflow-y:auto;scroll-margin-top:20px}.result-person{color:var(--accent);border:0;background:none;font-weight:650;cursor:pointer;padding:4px 0}.cell-meta{display:block;color:var(--text-secondary);font-size:12px}.condition-evidence{padding:14px 0;border-top:1px solid var(--border)}.condition-evidence p{margin:8px 0}.condition-evidence blockquote{margin:8px 0;padding:8px 12px;white-space:pre-wrap}.evidence-actions{display:flex;gap:8px;flex-wrap:wrap}.evidence-actions .el-button{margin:0}.match-diagnostics{margin-top:18px;font-size:12px}.match-diagnostics summary{cursor:pointer}.match-diagnostics pre{white-space:pre-wrap;overflow-wrap:anywhere}.pre-line{white-space:pre-wrap}@media(max-width:1100px){.match-result-layout{grid-template-columns:1fr}.match-evidence{max-height:none;overflow:visible}}@media(max-height:650px){.match-evidence{max-height:none}}
</style>
